import React,{useState} from "react";
import api from "../api";

function MealPlanPage(){

const [plan,setPlan]=useState("");

const load = async()=>{

 const res = await api.get(
  "/families/1/weekly-plan"
 );

 setPlan(res.data.plan);
};

return(
<div className="page">

<h1>Weekly Food Plan</h1>

<button onClick={load}>
Generate Plan
</button>

<pre>{plan}</pre>

</div>
);
}

export default MealPlanPage;
